const MODS=[['approvals','Approvals'],['orders','Orders & disputes'],['users','Users'],['reviews','Review moderation'],['comms','Communications'],['reports','Reports'],['catalog','Categories & listings'],['promos','Promotions']];
const ACTS=['view','edit'];
const curAdmin=()=>D().admins.find(a=>a.id===S.adminId)||D().admins[0];
const perm=(m,a='view')=>S.role==='super'||((curAdmin().perms[m]||[]).includes(a)&&curAdmin().status==='active');
const gate=(m,fn)=>perm(m,'view')?(perm(m,'edit')?'':alertBox('info',t('View-only: you can look but not change this section.'),'eye'))+fn():noPerm('Your admin account doesn’t include this module. Ask a Super Admin.');
const can=(m)=>perm(m,'edit');
const dis=(m)=>can(m)?'':'disabled title="'+t('You don’t have permission')+'"';
D().admins.forEach(a=>{a.perms.catalog=a.perms.catalog||(a.id==='ad1'?['view','edit']:a.id==='ad2'?['view']:[]);a.perms.promos=a.perms.promos||(a.id==='ad1'?['view','edit']:[])});
const allEnt=()=>[...D().biz.map(b=>({k:'biz',e:b})),...D().svc.map(s=>({k:'svc',e:s})),...D().riders.map(r=>({k:'rider',e:r}))];
function entOfApp(a){return a.ref?ent(a.ref):[...D().biz,...D().svc,...D().riders].find(e=>(nm(e.name)||e.name)===a.name)}
V.ahome=()=>{const os=D().orders,act=os.filter(o=>grp(o)==='active'),pend=D().apps.filter(a=>a.status==='pending'),cases=os.filter(o=>o.case&&o.case.status==='open'),rep=D().reviews.filter(r=>r.reported||r.status==='reported'),gmv=os.filter(o=>o.status!=='cancelled').reduce((a,o)=>a+orderTotal(o),0)+185000;
 return `<div class="stack-lg"><div class="row between wrap-r"><h1>${t('Platform overview')}</h1><span class="badge sec">${esc(S.role==='super'?'Super Admin':curAdmin().name)}</span></div>
 <div class="grid g4" style="grid-template-columns:repeat(auto-fit,minmax(150px,1fr))">${kpi('GMV (this month)',inr(gmv),'12%')}${kpi('Orders today',os.filter(o=>Date.now()-o.ts<DAY).length+38,'6%')}${kpi('Active deliveries',D().jobs.filter(j=>!['delivered','failed','requested'].includes(j.status)).length+3,'')}${kpi('Approvals pending',pend.length,'',false)}${kpi('Open cases',cases.length,'',false)}${kpi('Riders online',D().riders.filter(r=>r.online).length,'')}</div>
 <div class="cols2 eq"><div class="card pad stack"><div class="row between"><h3>${t('Approvals queue')}</h3><a class="btn t sm" href="#aappr">${t('See all')}</a></div>${pend.length?pend.map(a=>`<a class="row between" href="#aappr-${a.id}" style="min-height:48px"><span><b>${esc(a.name)}</b><span class="small t2" style="display:block">${t(a.type==='business'?'Business':a.type==='service'?'Service provider':'Rider')} · ${ago(a.ts)}</span></span>${apBadge(a.status)}</a>`).join(''):`<span class="muted small">${t('Nothing waiting. Great!')}</span>`}</div>
 <div class="card pad stack"><h3>${t('Alerts')}</h3>${[[cases.length,'Disputes & refund cases','aorders'],[rep.length,'Reported reviews','areviews'],[D().offers.filter(o=>o.status==='pending').length,'Offers to approve','apromos'],[D().jobs.filter(j=>j.status==='requested'&&Date.now()-j.ts>5*MIN).length,'Deliveries waiting for a rider','alive']].map(([n,l,r])=>`<a class="row between" href="#${r}" style="min-height:44px"><span>${t(l)}</span><span class="cnt" style="${n?'':'background:var(--surface-2);color:var(--muted)'}">${n}</span></a>`).join('')}</div></div>
 <div class="card pad stack"><div class="row between"><h3>${t('Live orders')}</h3><a class="btn t sm" href="#aorders">${t('See all')}</a></div>${tbl(['Order','Shop','Customer','Total','Status'],act.slice(0,6).map(o=>[`<a href="#aorder-${o.id}" style="color:var(--primary);font-weight:600">${o.id}</a>`,esc(nm(biz(o.bid).name)),esc(o.cust),inr(orderTotal(o)),stBadge(o.status,o)]))}</div></div>`};
V.aappr=arg=>gate('approvals',()=>{if(arg)return apprDetail(arg);const tab=UI.atab||'business',sf=UI.asf||'pending',l=D().apps.filter(a=>a.type===tab&&(sf==='all'||a.status===sf));
 return `<div class="stack"><h1>${t('Approvals')}</h1><div class="tabs">${[['business','Businesses'],['service','Service providers'],['rider','Riders']].map(([k,l])=>`<button class="${tab===k?'on':''}" data-act="atab" data-v="${k}">${t(l)} <span class="cnt" style="${D().apps.filter(a=>a.type===k&&a.status==='pending').length?'':'background:var(--surface-2);color:var(--text)'}">${D().apps.filter(a=>a.type===k&&a.status==='pending').length}</span></button>`).join('')}</div><div class="chips">${['pending','changes','approved','rejected','all'].map(s=>`<button class="chip ${sf===s?'on':''}" data-act="asf" data-v="${s}">${s==='all'?t('All'):t(AP[s][0])}</button>`).join('')}</div>${tbl(['Applicant','Owner','Phone','Area','Submitted','Status',''],l.map(a=>[`<b>${esc(a.name)}</b>`,esc(a.owner),a.phone,esc(a.area),ago(a.ts),apBadge(a.status),`<a class="btn p sm" href="#aappr-${a.id}">${t('Review')}</a>`]))}</div>`});
A.atab=el=>{UI.atab=el.dataset.v;render(true)};A.asf=el=>{UI.asf=el.dataset.v;render(true)};
function apprDetail(id){const a=D().apps.find(x=>x.id===id);if(!a)return V.nf();const di=UI.doc||0;
 return `<div class="stack-lg"><a class="btn t sm" href="#aappr" style="justify-self:start">${ic('cl',16)} ${t('Approvals')}</a><div class="row between wrap-r"><h1>${esc(a.name)}</h1>${apBadge(a.status)}</div><div class="cols2"><div class="stack"><div class="card pad stack"><h3>${t('Documents')}</h3><div class="chips">${a.docs.map((d,i)=>`<button class="chip ${di===i?'on':''}" data-act="doc" data-i="${i}">${esc(d)}</button>`).join('')}</div><div class="art w" style="--h:210;border-radius:var(--r-md);font-size:2.6rem"><span>📄</span></div><div class="small muted center">${esc(a.docs[di]||a.docs[0])} · ${t('Preview (sample document)')}</div><div class="row"><button class="btn g sm" data-act="fakeUpload">${ic('eye',14)} ${t('Zoom')}</button><button class="btn g sm" data-act="fakeUpload">${t('Mark document OK')}</button></div></div><div class="card pad stack"><h3>${t('Applicant')}</h3><dl class="kv"><dt>${t('Type')}</dt><dd>${t(a.type)}</dd><dt>${t('Owner')}</dt><dd>${esc(a.owner)}</dd><dt>${t('Phone')}</dt><dd><a href="${telH(a.phone)}">+91 ${esc(a.phone)}</a></dd><dt>${t('Area')}</dt><dd>${esc(a.area)}</dd><dt>${t('Submitted')}</dt><dd>${fdt(a.ts)}</dd></dl></div></div>
 <div class="stack"><div class="card pad stack"><h3>${t('Decision')}</h3><form data-form="decide" class="stack"><input type="hidden" name="id" value="${a.id}">${field('Reason / note to applicant','note','',{type:'textarea',hint:'Required for reject or change request'})}<div class="grid g2"><button class="btn p" name="d" value="approved" ${dis('approvals')}>${ic('check',18)} ${t('Approve')}</button><button class="btn d" name="d" value="rejected" ${dis('approvals')}>${ic('x',18)} ${t('Reject')}</button></div><button class="btn o" name="d" value="changes" ${dis('approvals')}>${ic('edit',18)} ${t('Request changes')}</button></form></div><div class="card pad stack"><h3>${t('History')}</h3>${a.hist.length?a.hist.map(h=>`<div class="small"><b>${esc(h.by)}</b> · ${apBadge(h.s)}<div class="t2">${esc(h.note)}</div><div class="xs muted">${fdt(h.ts)}</div></div>`).join(''):`<span class="muted small">${t('No actions yet')}</span>`}</div></div></div></div>`}
A.doc=el=>{UI.doc=+el.dataset.i;render(true)};
document.addEventListener('click',e=>{const b=e.target.closest('form[data-form=decide] button[name=d]');if(b)b.form.dataset.d=b.value},true);
F.decide=(d,f)=>{const dec=f.dataset.d;if(!dec)return;const a=D().apps.find(x=>x.id===d.id);if(!can('approvals')){toast(t('You don’t have permission'),'alert');return}if(dec!=='approved'&&!d.note.trim()){toast(t('Please add a note for the applicant'),'alert');return}
 const who=S.role==='super'?'Super Admin':curAdmin().name;let e=entOfApp(a);const before={status:a.status};
 if(dec==='approved'&&!e){const isR=a.type==='rider',isS=a.type==='service';const nid=(isR?'r':isS?'s':'b')+(100+D().biz.length+D().svc.length+D().riders.length);if(isR){e={id:nid,name:a.name,phone:a.phone,vehicle:'Bike',rating:0,rc:0,online:false,status:'approved',area:a.area};D().riders.push(e)}else{const ar=AREAS.find(x=>x.en===a.area)||AREAS[0];const cat=isS?'electrician':'grocery';e={id:nid,name:{en:a.name,hi:''},cat,emoji:catOf(cat).e,hue:catOf(cat).h,area:ar.id,addr:ar.en+', Padrauna',lat:ar.lat+.001,lng:ar.lng+.001,phone:a.phone,wa:a.phone,email:'',rating:0,rc:0,verified:true,status:'approved',desc:'',hours:H('09:00','20:00',[0]),social:{ig:'',yt:'',fb:''},gallery:['🏬'],closedNow:false,since:2026,...(isS?{services:[],serviceArea:'Padrauna'}:{del:{mode:'rider',radius:4,fee:20,min:150,pickup:true,note:''}})};(isS?D().svc:D().biz).push(e)}a.ref=nid}
 if(e)e.status=dec;a.status=dec;a.hist.push({by:who,s:dec,note:d.note||'Approved',ts:Date.now()});const role=a.type==='rider'?'rider':a.type==='service'?'provider':'vendor';
 notify(role,'Application '+(dec==='approved'?'approved':dec==='rejected'?'rejected':'needs changes'),d.note||'You can now go live.',role==='vendor'?'vhome':role==='provider'?'shome':'rhome','appr');audit('Application '+dec,a.name,before,{status:dec,note:d.note});save();toast(t('Decision saved')+': '+t(AP[dec][0]),'check');go('aappr')};
