V.alistings=()=>gate('catalog',()=>{const tab=UI.alt||'biz',l=tab==='biz'?D().biz:tab==='svc'?D().svc:D().riders;
 return `<div class="stack"><div class="row between wrap-r"><h1>${t('Listings')}</h1><button class="btn p sm" data-act="addEnt" ${dis('catalog')}>${ic('plus',16)} ${t('Add')}</button></div><div class="tabs">${[['biz','Businesses'],['svc','Service providers'],['rider','Riders']].map(([k,lb])=>`<button class="${tab===k?'on':''}" data-act="alt" data-v="${k}">${t(lb)}</button>`).join('')}</div>${tbl(['Name','Category / vehicle','Area','Rating','Status',''],l.map(e=>[`<b>${esc(nm(e.name)||e.name)}</b>`,esc(tab==='rider'?e.vehicle:catName(e.cat)),esc(tab==='rider'?e.area:areaName(e.area)),(e.rating||0).toFixed(1),apBadge(e.status),`<div class="row" style="gap:4px"><button class="btn g sm" data-act="entEdit" data-id="${e.id}" ${dis('catalog')}>${t('Edit')}</button>${tab!=='rider'?`<button class="btn g sm" data-act="prodMod" data-id="${e.id}">${t('Products')}</button>`:''}</div>`]))}</div>`});
A.alt=el=>{UI.alt=el.dataset.v;render(true)};
A.entEdit=el=>{const e=ent(el.dataset.id);sheet(`<h3>${t('Edit')} ${esc(nm(e.name)||e.name)}</h3><form data-form="entEdit" class="stack" style="margin-top:10px"><input type="hidden" name="id" value="${e.id}">${field('Name','name',nm(e.name)||e.name,{req:1})}${field('Phone','phone',e.phone,{type:'tel'})}${field('Status','status',e.status,{type:'select',opts:['approved','pending','rejected','suspended','inactive'].map(s=>[s,AP[s][0]])})}${field('Note (shown in audit log)','note','')}<div class="row"><button type="button" class="btn d grow" data-act="entDel" data-id="${e.id}">${t('Remove')}</button><button class="btn p grow">${t('Save')}</button></div></form>`)};
F.entEdit=d=>{const e=ent(d.id),before={name:nm(e.name)||e.name,status:e.status};if(typeof e.name==='object')e.name.en=d.name;else e.name=d.name;e.phone=d.phone;e.status=d.status;audit('Edited '+(d.id[0]==='b'?'business':d.id[0]==='s'?'service provider':'rider'),d.name+(d.note?' ('+d.note+')':''),before,{name:d.name,status:d.status});save();closeSheet();render(true);toast(t('Saved'))};
A.entDel=el=>confirmBox(t('Remove this listing?'),t('It will disappear from the app. This cannot be undone.'),t('Remove'),()=>{const id=el.dataset.id,e=ent(id);audit('Removed listing',nm(e.name)||e.name,{id},{});if(id[0]==='b'){D().biz=D().biz.filter(x=>x.id!==id);D().products=D().products.filter(p=>p.bid!==id)}else if(id[0]==='s')D().svc=D().svc.filter(x=>x.id!==id);else D().riders=D().riders.filter(x=>x.id!==id);save();render(true);toast(t('Removed'),'trash')},true);
