A.prodMod=el=>{const b=ent(el.dataset.id),l=D().products.filter(p=>p.bid===b.id);sheet(`<h3>${esc(nm(b.name))}: ${t('Products')}</h3><div class="stack" style="margin-top:10px">${l.map(p=>`<div class="row between"><span>${p.emoji} ${esc(nm(p.name))} <span class="badge ${p.status==='active'?'ok':'bad'}">${p.status}</span></span><button class="btn g sm" data-act="flagProd" data-id="${p.id}" ${dis('catalog')}>${p.status==='active'?t('Unpublish'):t('Publish')}</button></div>`).join('')||empty('📦','No products','')}</div>`,{wide:true})};
