/* orders & disputes */
const CASEST={open:['Open','warn'],review:['In review','info'],resolved:['Resolved','ok']};
V.aorders=()=>gate('orders',()=>{const f=UI.aof||'all';let l=D().orders;if(f==='active')l=l.filter(o=>grp(o)==='active');if(f==='cases')l=l.filter(o=>o.case);if(f==='refund')l=l.filter(o=>o.refund);if(f==='failed')l=l.filter(o=>o.cancel&&o.cancel.by==='rider');
 return `<div class="stack"><h1>${t('Orders & disputes')}</h1><div class="chips">${[['all','All'],['active','Active'],['cases','Disputes'],['refund','Refunds'],['failed','Failed deliveries']].map(([k,lb])=>`<button class="chip ${f===k?'on':''}" data-act="aof" data-v="${k}">${t(lb)}</button>`).join('')}</div>${tbl(['Order','Shop','Customer','Total','Status','Case',''],l.map(o=>[`<b>${o.id}</b>`,esc(nm(biz(o.bid).name)),esc(o.cust),inr(orderTotal(o)),stBadge(o.status,o),o.case?`<span class="badge ${CASEST[o.case.status][1]}">${t(o.case.type)} · ${t(CASEST[o.case.status][0])}</span>`:'-',`<a class="btn p sm" href="#aorder-${o.id}">${t('Open')}</a>`]))}</div>`});
A.aof=el=>{UI.aof=el.dataset.v;render(true)};
V.aorder=id=>gate('orders',()=>{const o=order(id);if(!o)return V.nf();const b=biz(o.bid),rd_=o.riderId?rider(o.riderId):null,job=D().jobs.find(j=>j.oid===id);
 return `<div class="stack-lg"><a class="btn t sm" href="#aorders" style="justify-self:start">${ic('cl',16)} ${t('All orders')}</a><div class="row between wrap-r"><h1>${o.id}</h1>${stBadge(o.status,o)}</div><div class="cols2"><div class="stack"><div class="card pad stack"><h3>${t('Order')}</h3>${o.items.map(i=>`<div class="row between small"><span>${i.emoji} ${esc(nm(i.name))} × ${i.qty}</span><span>${inr(i.price*i.qty)}</span></div>`).join('')}<dl class="kv"><dt>${t('Shop')}</dt><dd><a href="#biz-${b.id}">${esc(nm(b.name))}</a></dd><dt>${t('Customer')}</dt><dd>${esc(o.cust)} · +91 ${esc(o.phone)}</dd><dt>${t('Total')}</dt><dd>${inr(orderTotal(o))}</dd><dt>${t('Payment')}</dt><dd>${esc(o.pay.method)} · ${o.pay.status}</dd><dt>${t('Rider')}</dt><dd>${rd_?esc(rd_.name):'-'}</dd></dl></div><div class="card pad"><h3 style="margin-bottom:8px">${t('Timeline')}</h3>${timeline(o)}</div></div>
 <div class="stack"><div class="card pad stack"><h3>${t('Case workflow')}</h3>${o.case?`<div class="row between"><b>${esc(t(o.case.type))}</b><span class="badge ${CASEST[o.case.status][1]}">${t(CASEST[o.case.status][0])}</span></div>${(o.case.notes||[]).map(n=>`<div class="small t2">• ${esc(n)}</div>`).join('')}<form data-form="casenote" class="stack"><input type="hidden" name="id" value="${id}">${field('Add note','n','',{type:'textarea'})}<div class="grid g2"><button class="btn g" name="s" value="review" ${dis('orders')}>${t('Mark in review')}</button><button class="btn p" name="s" value="resolved" ${dis('orders')}>${t('Resolve')}</button></div></form>`:`<span class="muted small">${t('No dispute on this order.')}</span><button class="btn g sm" data-act="openCase" data-id="${id}" ${dis('orders')}>${t('Open a case')}</button>`}</div>
 ${o.refund?`<div class="card pad stack"><h3>${t('Refund')}</h3><div class="row between"><span class="badge info">${esc(o.refund.status)}</span><span>${inr(orderTotal(o))}</span></div><div class="grid g2"><button class="btn p" data-act="aRefund" data-id="${id}" data-v="approved" ${dis('orders')}>${t('Approve')}</button><button class="btn p" data-act="aRefund" data-id="${id}" data-v="completed" ${dis('orders')}>${t('Mark refunded')}</button></div></div>`:''}
 <div class="card pad stack"><h3>${t('Delivery & rider')}</h3>${o.mode==='delivery'?`<div class="small t2">${rd_?t('Assigned to')+' '+esc(rd_.name):t('No rider assigned')}</div><button class="btn o" data-act="aAssign" data-id="${id}" ${dis('orders')}>${rd_?t('Reassign rider'):t('Assign rider')}</button>`:`<span class="muted small">${t('Self-pickup order')}</span>`}</div><div class="row"><a class="btn g grow" href="${telH(o.phone)}">${ic('phone',16)} ${t('Call customer')}</a><a class="btn g grow" href="${telH(b.phone)}">${ic('phone',16)} ${t('Call shop')}</a></div></div></div></div>`});
document.addEventListener('click',e=>{const b=e.target.closest('form[data-form=casenote] button[name=s]');if(b)b.form.dataset.s=b.value},true);
F.casenote=(d,f)=>{const o=order(d.id);const s=f.dataset.s||'review';if(d.n)o.case.notes.push((S.role==='super'?'Super Admin':curAdmin().name)+': '+d.n);const before=o.case.status;o.case.status=s;if(s==='resolved'){notify('cust','Your request was resolved',o.id,'order-'+o.id,'order')}audit('Case '+s,o.id,{status:before},{status:s});save();render(true);toast(t('Case updated'))};
A.openCase=el=>{const o=order(el.dataset.id);o.case={type:'Problem',status:'open',notes:['Opened by admin']};save();render(true)};
A.aRefund=el=>{const o=order(el.dataset.id),v=el.dataset.v;o.refund.steps=o.refund.steps||[];if(!o.refund.steps.find(s=>s[0]===v))o.refund.steps.push([v,Date.now()]);o.refund.status=v;if(v==='completed'){o.pay.status='refunded';if(o.status==='cancelled'){}}audit('Refund '+v,o.id,{},{status:v});notify('cust','Refund '+v,o.id,'order-'+o.id,'order');save();render(true);toast(t('Refund updated'))};
A.aAssign=el=>{const o=order(el.dataset.id);sheet(`<h3>${t('Assign a rider')}</h3><div class="stack" style="margin-top:10px">${D().riders.filter(r=>r.status==='approved').map(r=>`<button class="card pad row" style="text-align:left" data-act="aDoAssign" data-id="${o.id}" data-r="${r.id}"><span class="grow"><b>${esc(r.name)}</b><span class="small t2" style="display:block">${esc(r.area)} · ${stars(r.rating)}</span></span><span class="badge ${r.online?'ok':'neu'}">${r.online?t('Online'):t('Offline')}</span></button>`).join('')}</div>`)};
A.aDoAssign=el=>{const o=order(el.dataset.id),r=rider(el.dataset.r);let j=D().jobs.find(x=>x.oid===o.id);if(!j){A.requestRider({dataset:{id:o.id}},true);j=D().jobs.find(x=>x.oid===o.id)}j.riderId=r.id;j.status=j.status==='requested'?'accepted':j.status;o.riderId=r.id;audit('Rider assigned',o.id+' → '+r.name,{},{rider:r.id});notify('rider','Delivery assigned by admin',o.id,'ractive','job');save();closeSheet();render(true);toast(t('Rider assigned'),'bike')};
V.alive=()=>gate('orders',()=>{const jobs=D().jobs.filter(j=>!['delivered','failed'].includes(j.status)),pins=[];jobs.forEach(j=>{const o=order(j.oid),b=biz(o.bid),pos=o.addrPos||addrPos();const p=j.status==='requested'?0:j.status==='pickedUp'?.5:j.status==='reachedDrop'?.95:.1;pins.push({id:j.id,name:{en:'Rider '+o.id},emoji:j.status==='requested'?'⏳':'🛵',lat:b.lat+(pos.lat-b.lat)*p,lng:b.lng+(pos.lng-b.lng)*p})});D().riders.filter(r=>r.online&&!jobs.some(j=>j.riderId===r.id)).forEach((r,i)=>pins.push({id:r.id,name:{en:r.name+' (idle)'},emoji:'🟢',lat:CENTER.lat+(i-1)*.004,lng:CENTER.lng+(i+1)*.003}));
 return `<div class="stack"><div class="row between"><h1><span class="livedot"></span>${t('Live deliveries')}</h1></div>${mapSvg('livemap',pins,{noMe:true})}<div class="small muted">🛵 ${t('on a delivery')} · ⏳ ${t('waiting for rider')} · 🟢 ${t('idle online rider')}</div>${tbl(['Order','Shop','Rider','Status',''],jobs.map(j=>{const o=order(j.oid);return [`<a href="#aorder-${o.id}" style="color:var(--primary);font-weight:600">${o.id}</a>`,esc(nm(biz(o.bid).name)),j.riderId?esc(rider(j.riderId).name):'-',`<span class="badge info">${t(jobLabel(j.status))}</span>`,`<button class="btn g sm" data-act="aAssign" data-id="${o.id}" ${dis('orders')}>${j.riderId?t('Reassign'):t('Assign')}</button>`]}))}</div>`});
V.areviews=()=>gate('reviews',()=>{const f=UI.arf||'rep',l=D().reviews.filter(r=>f==='rep'?(r.reported||r.status==='reported')&&r.status!=='hidden':f==='pend'?r.status==='pending':r.status==='hidden');
 return `<div class="stack"><h1>${t('Review moderation')}</h1><div class="chips">${[['rep','Reported'],['pend','Pending'],['hid','Removed']].map(([k,lb])=>`<button class="chip ${f===k?'on':''}" data-act="arf" data-v="${k}">${t(lb)}</button>`).join('')}</div>${l.length?l.map(r=>`<div class="card pad stack"><div class="small muted">${t('On')}: ${esc(nm((ent(r.tid)||{name:r.tid}).name))} · ${r.reports||0} ${t('report(s)')}</div>${revCard(r,'none')}<div class="row wrap-r"><button class="btn p sm" data-act="rmod" data-id="${r.id}" data-v="published" ${dis('reviews')}>${t('Approve')}</button><button class="btn g sm" data-act="rmod" data-id="${r.id}" data-v="hidden" ${dis('reviews')}>${t('Hide')}</button><button class="btn d sm" data-act="rmod" data-id="${r.id}" data-v="deleted" ${dis('reviews')}>${t('Delete')}</button></div></div>`).join(''):empty('✅','Queue is clear','No reviews need attention.')}</div>`});
A.arf=el=>{UI.arf=el.dataset.v;render(true)};
A.rmod=el=>{const r=D().reviews.find(x=>x.id===el.dataset.id),v=el.dataset.v;const before=r.status;if(v==='deleted')D().reviews=D().reviews.filter(x=>x!==r);else{r.status=v;if(v==='published'){r.reported=false;r.reports=0}}audit('Review '+v,'Review by '+r.name,{status:before},{status:v});save();render(true);toast(t('Done'))};
V.apromos=()=>gate('promos',()=>{const pend=D().offers.filter(o=>o.status==='pending');return `<div class="stack-lg"><h1>${t('Promotions & offers')}</h1><div class="card pad stack"><h3>${t('Vendor offers awaiting approval')}</h3>${pend.length?pend.map(o=>`<div class="row between wrap-r"><span><b>${esc(o.title)}</b><span class="small t2" style="display:block">${esc(nm(biz(o.bid).name))} · ${t('till')} ${fdate(o.to)}</span></span><span class="row"><button class="btn p sm" data-act="offAp" data-id="${o.id}" data-v="active" ${dis('promos')}>${t('Approve')}</button><button class="btn g sm" data-act="offAp" data-id="${o.id}" data-v="ended" ${dis('promos')}>${t('Reject')}</button></span></div>`).join(''):`<span class="muted small">${t('No offers waiting.')}</span>`}</div><div class="card pad stack"><div class="row between"><h3>${t('Homepage banners')}</h3><button class="btn g sm" data-act="bnAdd" ${dis('promos')}>${ic('plus',14)} ${t('Add')}</button></div>${D().banners.map(b=>`<div class="row"><div class="mini art" style="background:linear-gradient(120deg,${b.c1},${b.c2});width:56px;height:36px;border-radius:8px"></div><div class="grow"><b>${esc(b.t)}</b><div class="small t2">${esc(b.s)}</div></div><span class="toggle"><input type="checkbox" ${b.on?'checked':''} data-chg="bnOn" data-id="${b.id}" ${dis('promos')} aria-label="${t('Show')}"><span></span></span></div>`).join('')}</div><div class="card pad stack"><h3>${t('Featured businesses')}</h3>${D().biz.map(b=>`<div class="row between"><span>${b.emoji} ${esc(nm(b.name))}</span><span class="toggle"><input type="checkbox" ${b.featured?'checked':''} data-chg="featOn" data-id="${b.id}" ${dis('promos')} aria-label="${t('Featured')}"><span></span></span></div>`).join('')}</div></div>`});
A.offAp=el=>{const o=D().offers.find(x=>x.id===el.dataset.id);o.status=el.dataset.v;audit('Offer '+o.status,o.title,{},{status:o.status});notify('vendor','Offer '+(o.status==='active'?'approved':'rejected'),o.title,'voffers','admin');save();render(true);toast(t('Done'))};
CH.bnOn=el=>{D().banners.find(b=>b.id===el.dataset.id).on=el.checked;save();toast(t('Updated'))};CH.featOn=el=>{biz(el.dataset.id).featured=el.checked;save();toast(t('Updated'))};
A.bnAdd=()=>sheet(`<h3>${t('Add banner')}</h3><form data-form="bnAdd" class="stack" style="margin-top:10px">${field('Title','t','',{req:1})}${field('Subtitle','s','')}${field('Links to (page)','link','offers')}<button class="btn p">${t('Add')}</button></form>`);F.bnAdd=d=>{D().banners.push({id:rid('bn'),t:d.t,s:d.s,c1:'#C2410C',c2:'#7C2D12',link:d.link||'offers',on:true});save();closeSheet();render(true)};
/* communications */
const TPL={offer:['Offer','Hi! {shop} has a special offer for you: {offer}. Order now on ApnaTown: {link}'],newp:['New product','{shop} just added new products. Take a look: {link}'],fest:['Festival greeting','Happy festival from {shop}! Enjoy a special discount this week: {link}'],delay:['Delay apology','Sorry! Your order from {shop} is slightly delayed. Thank you for waiting.']};
UI.cm={target:'b1',tpl:'offer',ch:{wa:true,app:true,email:false},sched:'now',when:''};
const audSize=id=>{const h=[...id].reduce((a,c)=>a+c.charCodeAt(0),0);return 120+(h*37)%380};
V.acomms=()=>gate('comms',()=>{const c=UI.cm,e=ent(c.target),n=audSize(c.target),waOk=Math.round(n*.62),inapp=Math.round(n*.9),em=Math.round(n*.48);const msg=UI.cmMsg??TPL[c.tpl][1];const prev=msg.replace('{shop}',nm(e.name)).replace('{offer}','10% off').replace('{link}',shareUrl('biz-'+e.id));
 return `<div class="stack-lg"><h1>${t('Communications')}</h1><div class="cols2"><div class="stack"><div class="card pad stack"><h3>1. ${t('Audience')}</h3>${field('Send to customers of','target',c.target,{type:'select',opts:[...D().biz.map(b=>[b.id,'🏪 '+b.name.en]),...D().svc.map(s=>[s.id,'🔧 '+s.name.en]),...D().products.slice(0,10).map(p=>[p.id,'📦 '+p.name.en])]})}<div class="grid g3 center"><div class="card pad"><b>${n}</b><div class="xs muted">${t('Total audience')}</div></div><div class="card pad"><b style="color:var(--success)">${c.ch.wa?waOk:0}</b><div class="xs muted">${t('WhatsApp with consent')}</div></div><div class="card pad"><b>${n-waOk}</b><div class="xs muted">${t('Excluded (no opt-in)')}</div></div></div>${alertBox('info',t('Only customers who opted in to WhatsApp offers are counted. Opted-out numbers are never messaged.'),'shield')}</div>
 <div class="card pad stack"><h3>2. ${t('Channels')}</h3>${[['wa','WhatsApp Business',waOk],['app','In-app notification',inapp],['email','Email',em]].map(([k,l,x])=>`<label class="check"><input type="checkbox" ${c.ch[k]?'checked':''} data-chg="cmch" data-k="${k}" style="accent-color:var(--primary)"> ${l} <span class="muted small">(${x})</span></label>`).join('')}</div>
 <div class="card pad stack"><h3>3. ${t('Template & message')}</h3><div class="chips">${Object.entries(TPL).map(([k,v])=>`<button class="chip ${c.tpl===k?'on':''}" data-act="cmtpl" data-v="${k}">${t(v[0])}</button>`).join('')}</div><textarea class="input" data-in="cmmsg" aria-label="${t('Message')}" rows="4">${esc(msg)}</textarea><div class="xs muted">${t('Variables')}: {shop} {offer} {link}. ${t('WhatsApp templates need prior approval from Meta.')}</div></div>
 <div class="card pad stack"><h3>4. ${t('Schedule')}</h3><div class="chips"><button class="chip ${c.sched==='now'?'on':''}" data-act="cmsch" data-v="now">${t('Send now')}</button><button class="chip ${c.sched==='later'?'on':''}" data-act="cmsch" data-v="later">${t('Schedule')}</button></div>${c.sched==='later'?`<input class="input" type="datetime-local" data-in="cmwhen" value="${esc(c.when)}" aria-label="${t('Date and time')}">`:''}</div></div>
 <div class="stack"><div class="card pad stack" style="position:sticky;top:76px"><h3>${t('Preview')}</h3><div style="background:#DCF8C6;color:#111;padding:12px 14px;border-radius:12px 12px 12px 2px;white-space:pre-wrap;font-size:.92rem">${esc(prev)}<div class="xs" style="opacity:.6;margin-top:4px">${t('Reply STOP to opt out')} · ${ftime(Date.now())}</div></div><div class="small t2">${t('Recipients')}: <b>${(c.ch.wa?waOk:0)+(c.ch.app?inapp:0)+(c.ch.email?em:0)}</b> ${t('messages across selected channels')}</div><button class="btn p block" data-act="cmsend" ${can('comms')&&(c.ch.wa||c.ch.app||c.ch.email)?'':'disabled'}>${ic('send',18)} ${c.sched==='later'?t('Schedule campaign'):t('Send now')}</button></div></div></div>
 <div class="card pad stack"><h3>${t('Delivery reports')}</h3>${tbl(['When','Target','Channels','Sent','Delivered','Failed','Opt-outs','Status'],D().comms.map(m=>[fdt(m.ts),esc(m.target),m.ch.join(', '),m.sent,m.delivered,m.failed,m.optout,`<span class="badge ${m.status==='sent'?'ok':'warn'}">${t(m.status==='sent'?'Sent':'Scheduled')}</span>`]))}</div></div>`});
CH.cmch=el=>{UI.cm.ch[el.dataset.k]=el.checked;render(true)};A.cmtpl=el=>{UI.cm.tpl=el.dataset.v;UI.cmMsg=undefined;render(true)};A.cmsch=el=>{UI.cm.sched=el.dataset.v;render(true)};INP.cmmsg=v=>{UI.cmMsg=v};INP.cmwhen=v=>{UI.cm.when=v};
document.addEventListener('change',e=>{if(e.target.name==='target'&&e.target.closest('#main')&&cur().name==='acomms'){UI.cm.target=e.target.value;render(true)}});
A.cmsend=()=>{const c=UI.cm,e=ent(c.target),n=audSize(c.target),wa=Math.round(n*.62);const chs=[c.ch.wa&&'WhatsApp',c.ch.app&&'In-app',c.ch.email&&'Email'].filter(Boolean);const sent=(c.ch.wa?wa:0)+(c.ch.app?Math.round(n*.9):0);const m={id:rid('c'),ts:c.sched==='later'&&c.when?new Date(c.when).getTime():Date.now(),target:nm(e.name),ch:chs,tpl:c.tpl,sent,delivered:Math.round(sent*.95),failed:Math.round(sent*.05),optout:Math.round(sent*.01),status:c.sched==='later'?'scheduled':'sent'};D().comms.unshift(m);if(c.ch.app)notify('cust','Offer from '+nm(e.name),(UI.cmMsg??TPL[c.tpl][1]).replace('{shop}',nm(e.name)).replace('{offer}','10% off').replace('{link}',''),'offers','offer');audit('Campaign '+m.status,nm(e.name)+' via '+chs.join('/'),{},{recipients:sent});save();render(true);toast(c.sched==='later'?t('Campaign scheduled'):t('Campaign sent'),'send')};
/* reports */
V.areports=()=>gate('reports',()=>{const tab=UI.art||'orders',os=D().orders;
 const byBiz=D().biz.map(b=>{const o=os.filter(x=>x.bid===b.id);return [esc(nm(b.name)),o.length+series(b.id,1,20,60)[0],inr(o.reduce((a,x)=>a+orderTotal(x),0)+series(b.id,1,12000,40000)[0]),b.rating.toFixed(1)]}).sort((a,b)=>b[1]-a[1]);
 const body=tab==='orders'?`<div class="card pad stack"><h3>${t('Orders per day')}</h3>${barChart(series('ord',7,30,40),lastDays(7))}</div><div class="card pad row between"><span>${t('Order mix')}</span>${donut([['d',os.filter(o=>o.mode==='delivery').length+22,'var(--primary)'],['p',os.filter(o=>o.mode==='pickup').length+9,'var(--secondary)']])}</div>`:tab==='revenue'?`<div class="card pad stack"><h3>${t('Revenue (GMV) per day')}</h3>${barChart(series('rev',7,18000,26000),lastDays(7),inr)}</div>${kpi('Platform commission (month)',inr(14230),'8%')}`:tab==='vendors'?tbl(['Vendor','Orders','Revenue','Rating'],byBiz):tab==='riders'?tbl(['Rider','Deliveries','Rating','Avg earning/ride'],D().riders.map(r=>[esc(r.name),r.rc,r.rating,inr(42)])):tbl(['Provider','Enquiries (30d)','Converted','Rating'],D().svc.map(s=>[esc(nm(s.name)),series(s.id,1,12,20)[0],series(s.id,1,3,8)[0],s.rating]));
 return `<div class="stack-lg"><h1>${t('Reports')}</h1><div class="chips">${[['orders','Orders'],['revenue','Revenue'],['vendors','Vendor performance'],['riders','Rider performance'],['enq','Enquiries']].map(([k,lb])=>`<button class="chip ${tab===k?'on':''}" data-act="art" data-v="${k}">${t(lb)}</button>`).join('')}<button class="chip" data-act="exportCsv">${ic('upload',14)} ${t('Export CSV')}</button></div>${body}</div>`});
A.art=el=>{UI.art=el.dataset.v;render(true)};A.exportCsv=()=>{const rows=['order,shop,total,status',...D().orders.map(o=>[o.id,nm(biz(o.bid).name),orderTotal(o),o.status].join(','))].join('\n');sheet(`<h3>${t('Export')}</h3><p class="small muted">${t('Copy the CSV below.')}</p><div class="pre">${esc(rows)}</div><button class="btn p block" data-act="copy" data-v="${esc(rows)}">${t('Copy CSV')}</button>`)};
const auditTbl=(l)=>tbl(['When','Who','Action','Detail','Before → After'],l.map(a=>[fdt(a.ts),esc(a.actor),`<b>${esc(a.action)}</b>`,esc(a.detail),`<code class="xs">${esc(JSON.stringify(a.before))} → ${esc(JSON.stringify(a.after))}</code>`]));
V.aaudit=()=>{if(S.role!=='super'&&!perm('reports','view'))return noPerm();const q=(UI.aaq||'').toLowerCase(),l=D().audit.filter(a=>!q||(a.actor+a.action+a.detail).toLowerCase().includes(q));return `<div class="stack"><h1>${t('Audit log')}</h1><div class="searchbar">${ic('search',18)}<input data-in="aaq" value="${esc(UI.aaq||'')}" placeholder="${t('Search actions')}" aria-label="${t('Search')}"></div><div id="audl">${auditTbl(l)}</div></div>`};
INP.aaq=v=>{UI.aaq=v;const q=v.toLowerCase();$('#audl').innerHTML=auditTbl(D().audit.filter(a=>!q||(a.actor+a.action+a.detail).toLowerCase().includes(q)))};
V.aprofile=()=>{const a=S.role==='super'?{name:'Super Admin',email:'super@apnatown.in',areas:AREAS.map(x=>x.id)}:curAdmin();return `<div class="stack"><h1>${t('Admin profile')}</h1><div class="card pad stack"><div class="row"><div class="art mini" style="border-radius:50%">${esc(a.name[0])}</div><div><b>${esc(a.name)}</b><div class="small t2">${esc(a.email)}</div></div></div><div><div class="lbl small">${t('Assigned areas')}</div><div class="chips" style="flex-wrap:wrap">${a.areas.map(x=>`<span class="chip">${esc(nm(areaOf(x)))}</span>`).join('')||`<span class="muted small">${t('None yet')}</span>`}</div></div></div><div class="card pad stack"><h3>${t('My permissions')}</h3>${MODS.map(([k,l])=>`<div class="row between small"><span>${t(l)}</span><span>${S.role==='super'?'view, edit':(curAdmin().perms[k]||[]).join(', ')||'—'}</span></div>`).join('')}</div><div class="card pad row between"><span>${t('Language')}</span><button class="btn g sm" data-act="lang">${S.lang==='en'?'हिन्दी':'English'}</button></div></div>`};
